extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve caricarsi senza errori"):
		return
	var turret := find_by_name(main, "Turret") as Node3D
	if not check("turret", turret != null, "La scena deve contenere un nodo chiamato Turret"):
		return
	var target := find_by_name(main, "Target") as Node3D
	if not check("target", target != null, "La scena deve contenere un nodo chiamato Target"):
		return

	turret.rotation.y = 0.0
	target.global_position = Vector3(10.0, 0.0, 0.0)

	await wait_physics_frames(10)

	var rot_1: float = turret.rotation.y
	check("turning", absf(rot_1) > 0.02, "La torretta deve ruotare verso il bersaglio assegnato (rotazione Y attuale: %.2f)" % rot_1)

	await wait_physics_frames(60)

	var expected_angle: float = atan2(-10.0, 0.0)
	var diff: float = absf(angle_difference(turret.rotation.y, expected_angle))
	check("aimed", diff < 0.2, "Dopo tempo sufficiente la torretta deve essere rivolta verso il bersaglio (rotazione Y attuale: %.2f, attesa: %.2f)" % [turret.rotation.y, expected_angle])

